import json,pathlib,sys
plan=json.loads(pathlib.Path(sys.argv[1]).read_text());atoms=plan['atoms'];owners={}
for piece in plan['pieces']:
 for atom in piece['atoms']:
  assert atom not in owners
  owners[atom]=piece['id']
assert set(owners)=={a['id'] for a in atoms}
issues=[];count=0
for path in sys.argv[2:]:
 for row in map(json.loads,pathlib.Path(path).read_text().splitlines()):
  for unit in row.get('units',[]):
   if unit['status']!='deferred_generic_instantiation':continue
   count+=1
   found=[a for a in atoms if a['start']<=unit['body_start']<unit['body_end']<=a['end']]
   assert len(found)==1,(unit['where'],found)
   expected=owners[found[0]['id']];actual=row['piece']['id']
   if expected!=actual:issues.append(dict(where=unit['where'],name=unit.get('name',''),expected_piece=expected,actual_piece=actual,atom=found[0]['id']))
print(json.dumps(dict(exact_ownership=not issues,deferred_units=count,issues=issues),indent=2));sys.exit(1 if issues else 0)
